from pathlib import Path
from html.parser import HTMLParser
class Text(HTMLParser):
 def __init__(self): super().__init__(); self.parts=[]
 def handle_data(self,data):
  if data.strip(): self.parts.append(data.strip())
p=Path('products/distribution/workers-dev-policy')
for f in sorted(p.glob('*')):
 print('FILE',str(f))
 if f.suffix=='.html':
  parser=Text(); parser.feed(f.read_text()); lines=parser.parts
  hits=[i for i,s in enumerate(lines) if any(k in s.lower() for k in ['indexing','search engine','noindex','production','custom domain'])]
  for i in hits:
   print('\n'.join(lines[max(0,i-2):i+4]))
 else: print(f.read_text()[:18000])
